            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_order_id = None
        self.no_entry_today = False
        self.last_processed_date = None

    def OnFiveMinuteBar(self, sender, bar):
        # Regular-session minute data naturally produces bars ending at
        # 09:35, 09:40, and so on. Missing bars are not synthesized.
        if bar.Symbol != self.spy:
            return

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if old_fast is None or old_slow is None:
            return

        current_time = bar.EndTime.time()
        if current_time < time(9, 45) or current_time > time(14, 30):
            return

        if old_fast <= old_slow and self.fast.Current.Value > self.slow.Current.Value:
            self.pending_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.last_processed_date != current_date:
            self.last_processed_date = current_date
            self.no_entry_today = False

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self.EvaluateProfitTarget(slice)
            self.EvaluateTimeStop()
        elif self.entry_symbol is None and self.entry_order_id is None and not self.no_entry_today:
            if self.pending_signal:
                self.pending_signal = False
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.entry_symbol is not None or self.entry_order_id is not None:
            return

        if not slice.OptionChains.ContainsKey(self.option_canonical):
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        chain = slice.OptionChains[self.option_canonical]
        algorithm_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration")
            return

        selected_expiry = expirations[0]
        spy_price = self.Securities[self.spy].Price

        if spy_price <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price")
            return

        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry; no qualifying call for "
                f"{selected_expiry}"
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId

        self.Debug(
            f"{self.Time}: submitted entry for {selected.Symbol}; "
            f"expiry={selected_expiry}, strike={selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        if not slice.ContainsKey(self.entry_symbol):
            return

        quote = slice[self.entry_symbol]
        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("profit target")

    def EvaluateTimeStop(self):
        if self.entry_symbol is None or self.exit_order_id is not None:
            return

        security = self.Securities[self.entry_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        previous_trading_day = self.PreviousTradingDay(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")

    def HandleExpirationProcessing(self):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_today = True

            if self.Portfolio[self.entry_symbol].Quantity != 0:
                self.SubmitExit("unexpected expiration holding")

    def SubmitExit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_order_id is not None:
            return

        if self.entry_symbol in self.Transactions.GetOpenOrders(self.entry_symbol):
            for order in self.Transactions.GetOpenOrders(self.entry_symbol):
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        self.exit_order_id = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        ).OrderId

        self.Debug(f"{self.Time}: submitted exit for {reason}")

    def HandleUnexpectedEquityPosition(self):
        holdings = self.Portfolio[self.spy].Quantity
        if holdings != 0:
            self.no_entry_today = True
            self.Debug(
                f"{self.Time}: unexpected SPY equity position detected; "
                f"liquidating {holdings} shares"
            )
            self.MarketOrder(self.spy, -holdings, tag="unexpected exercise/assignment")

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id:
            self.entry_order_id = None
            self.entry_price = order_event.FillPrice

            self.Debug(
                f"{self.Time}: entry filled for {self.entry_symbol} "
                f"at {self.entry_price}"
            )

        elif order_event.OrderId == self.exit_order_id:
            self.exit_order_id = None
            self.Debug(f"{self.Time}: exit filled for {self.entry_symbol}")

            if not self.Portfolio[self.entry_symbol].Invested:
                self.entry_symbol = None
                self.entry_price = None
