from AlgorithmImports import *


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2021, 1, 1)
        self.SetEndDate(2023, 12, 31)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.last_fast = None
        self.last_slow = None
        self.last_chain = None

        self.held_option = None
        self.entry_order = None
        self.exit_order = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self.last_chain = None

        for chain in slice.OptionChains.Values:
            if chain.Symbol == self.option.Symbol:
                self.last_chain = chain
                break

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationSafeguards()

        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]

        if not holding.Invested or self.exit_order is not None:
            return

        contract = None
        if self.last_chain is not None:
            for candidate in self.last_chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("profit target")

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end_time = bar.EndTime
        end_clock = end_time.time()

        # Regular-session bars only. The first valid bar ends at 09:35.
        if end_clock < time(9, 35) or end_clock > time(16, 0):
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, bar.Close)
        self.slow.Update(end_time, bar.Close)

        if previous_fast is None or previous_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= end_clock <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_order is not None and not self.entry_order.Status.IsClosed():
            return

        self.TryEnterCall()

    def TryEnterCall(self):
        if self.last_chain is None:
            self.Debug("Skipped entry: current Slice has no SPY option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in self.last_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        expiry_date = expirations[0]
        threshold = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in self.last_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry_date
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_order = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={expiry_date} strike={selected.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order is not None:
            if order_event.OrderId == self.entry_order.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self.held_option} "
                        f"price={self.entry_price}"
                    )
                    self.entry_order = None
                elif order_event.Status == OrderStatus.Canceled:
                    self.entry_order = None

        if self.exit_order is not None:
            if order_event.OrderId == self.exit_order.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )
                    self.exit_order = None
                    self.held_option = None
                    self.entry_price = None
                elif order_event.Status == OrderStatus.Canceled:
                    self.exit_order = None

    def SubmitExit(self, reason):
        if self.held_option is None or self.exit_order is not None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity == 0:
            return

        if self.entry_order is not None and not self.entry_order.Status.IsClosed():
            self.entry_order.Cancel("Exit required")
            self.entry_order = None

        if self.exit_order is not None and not self.exit_order.Status.IsClosed():
            self.exit_order.Cancel("Replacing exit order")

        self.exit_order = self.MarketOrder(
            self.held_option,
            -holding.Quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option} reason={reason}")

    def HandleExpirationSafeguards(self):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry:
            self.no_entry_date = current_date
            self.SubmitExit("expiration safeguard")
            return

        previous_trading_day = expiry - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(previous_trading_day, time())
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"liquidating {holding.Quantity} SPY shares."
            )
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
